def pascal_triangle(n):
    triangle = [[0] * i for i in range(n + 1)]
    for line in range(n + 1):
        triangle[line][0] = 1
        triangle[line][line] = 1
        for internal in range(1, line):
            triangle[line][internal] = triangle[line - 1][internal - 1] + triangle[line - 1][internal]
    return triangle

def print_pascal_triangle(n):
    triangle = pascal_triangle(n)
    for line in triangle:
        print(' '.join(str(num) for num in line))

